// Participants is the resolver for the participants field.
func (r *trainingPlanResolver) Participants(ctx context.Context, obj *types.TrainingPlan, status *coredata.TrainingParticipantStatus) ([]*types.TrainingParticipant, error) {
	// Participants carry profile details (email, department).
	if _, err := r.authorize(ctx, obj.ID, iam.ActionMembershipProfileList); err != nil {
		return nil, err
	}

	scope, err := r.authorize(ctx, obj.ID, probo.ActionTrainingPlanGet)
	if err != nil {
		return nil, err
	}

	participants, err := r.listTrainingParticipants(ctx, scope, obj.ID)
	if err != nil {
		return nil, err
	}

	result := make([]*types.TrainingParticipant, 0, len(participants))
	for _, p := range participants {
		if status == nil || p.Progress.Status == *status {
			result = append(result, NewTrainingParticipant(p))
		}
	}

	return result, nil
}

